options.afterRender:
/**
 * Draws one card per commit on its way to the cluster.
 * A card carries the phases of the run, a chip per step, and a clock that keeps
 * counting between refreshes so the card moves with the event feed.
 */
const element = context.element;
const theme = context.grafana.theme;

/** Order decides which steps a delivery has already passed. */
const STAGES = [
  'started',
  'waiting_for_build',
  'building_image',
  'waiting_for_renovate',
  'renovate_running',
  'waiting_for_merge',
  'waiting_for_argocd',
  'argocd_syncing',
  'rolling_out',
  'finished',
];
const FAILED = ['build_failed', 'renovate_failed', 'sync_failed', 'degraded'];

/** Phases the cluster moves a commit through, drawn left to right. */
const PHASES = [
  {
    name: 'build',
    chips: [
      { label: 'queued', stages: ['started', 'waiting_for_build'], link: 'pipeline_url' },
      { label: 'image', stages: ['building_image'], link: 'pipeline_url' },
    ],
  },
  {
    name: 'renovate',
    chips: [
      { label: 'queued', stages: ['waiting_for_renovate'], link: 'renovate_url' },
      { label: 'bump', stages: ['renovate_running'], link: 'renovate_url' },
    ],
  },
  {
    name: 'merge',
    chips: [{ label: 'request', stages: ['waiting_for_merge'], link: 'mr_url' }],
  },
  {
    name: 'deploy',
    chips: [
      { label: 'queued', stages: ['waiting_for_argocd'], link: 'argocd_url' },
      { label: 'sync', stages: ['argocd_syncing'], link: 'argocd_url' },
      { label: 'rollout', stages: ['rolling_out'], link: 'argocd_url' },
    ],
  },
  {
    name: 'live',
    chips: [{ label: 'healthy', stages: ['finished'], link: 'app_url' }],
  },
];

const MARKS = { done: '✓', failed: '✕', pending: '', running: '' };

/** Colors follow the dashboard theme, so the card reads in light and dark. */
const palette = {
  '--pdx-text': theme.colors.text.primary,
  '--pdx-dim': theme.colors.text.secondary,
  '--pdx-link': theme.colors.text.link,
  '--pdx-border': theme.colors.border.weak,
  '--pdx-panel': theme.colors.background.primary,
  '--pdx-phase': theme.colors.background.secondary,
  '--pdx-chip': theme.colors.background.primary,
  '--pdx-ok': theme.colors.success.text,
  '--pdx-bad': theme.colors.error.text,
  '--pdx-run': theme.colors.primary.text,
  '--pdx-accent': theme.colors.border.strong,
  '--pdx-mono': theme.typography.fontFamilyMonospace,
};
Object.keys(palette).forEach((key) => element.style.setProperty(key, palette[key]));

/** Frames arrive one per query. Reading them by refId keeps order out of it. */
const frames = {};
((context.panelData && context.panelData.series) || []).forEach((frame) => {
  frames[frame.refId] = frame;
});

/** Rows of a frame as plain objects, the sample value under `value`. */
const readRows = (refId) => {
  const frame = frames[refId];
  if (!frame || !frame.fields || !frame.length) {
    return [];
  }
  const valueField = frame.fields.find((field) => field.type === 'number');
  const out = [];
  for (let i = 0; i < frame.length; i++) {
    const row = { value: 0 };
    frame.fields.forEach((field) => {
      const value = field.values.get ? field.values.get(i) : field.values[i];
      if (field === valueField) {
        row.value = value;
      } else {
        row[field.name] = value;
      }
    });
    out.push(row);
  }
  return out;
};

/**
 * One row per commit. A stage change writes a new label set and the set it
 * replaced answers for another few seconds, so the highest transition count wins.
 */
const deliveries = new Map();
readRows('A').forEach((row) => {
  const held = deliveries.get(row.sha);
  if (!held || row.value > held.value) {
    deliveries.set(row.sha, row);
  }
});

/** Seconds keyed by commit and stage, matching a row to its own label set. */
const keyed = (refId) => {
  const out = {};
  readRows(refId).forEach((row) => {
    out[row.sha + '|' + row.stage] = row.value;
  });
  return out;
};
const elapsed = keyed('B');
const total = keyed('C');
const spent = keyed('D');

/** Address each service answers on, for the chip that closes a delivery. */
const liveUrl = {};
readRows('E').forEach((row) => {
  if (row.url) {
    liveUrl[row.app] = row.url;
  }
});

const clocks = [];
const started = Date.now();

const format = (seconds) => {
  if (seconds === undefined || seconds === null || isNaN(seconds)) {
    return '';
  }
  if (seconds < 60) {
    return (seconds < 10 ? seconds.toFixed(1) : Math.round(seconds)) + 's';
  }
  const minutes = Math.floor(seconds / 60);
  if (minutes < 60) {
    return minutes + 'm ' + Math.round(seconds % 60) + 's';
  }
  return Math.floor(minutes / 60) + 'h ' + (minutes % 60) + 'm';
};

const add = (parent, tag, className, text) => {
  const node = document.createElement(tag);
  if (className) {
    node.className = className;
  }
  if (text !== undefined) {
    node.textContent = text;
  }
  parent.appendChild(node);
  return node;
};

/** A link where the tracker knows the address, plain text where it does not. */
const link = (parent, className, text, href) => {
  const node = add(parent, href ? 'a' : 'span', className, text);
  if (href) {
    node.href = href;
    node.target = '_blank';
    node.rel = 'noreferrer';
  }
  return node;
};

/** Seconds a clock shows now, counting on from the sample it was drawn with. */
const tick = () => {
  const drifted = (Date.now() - started) / 1000;
  clocks.forEach((clock) => {
    clock.node.textContent = format(clock.base + drifted);
  });
};

const root = document.createElement('div');
root.className = 'pdx';

const settled = (row) => (row.stage === 'finished' || FAILED.indexOf(row.stage) !== -1 ? 1 : 0);
const age = (row) => total[row.sha + '|' + row.stage] || 0;

const rows = Array.from(deliveries.values()).sort((left, right) => {
  return settled(left) - settled(right) || age(left) - age(right);
});

if (!rows.length) {
  add(root, 'div', 'pdx-empty', 'Nothing has been delivered in the last ten minutes.');
}

rows.forEach((delivery) => {
  const failed = FAILED.indexOf(delivery.stage) !== -1;
  const done = delivery.stage === 'finished';
  const at = STAGES.indexOf(delivery.step || delivery.stage);
  const live = elapsed[delivery.sha + '|' + delivery.stage];
  const app = delivery.app || '';

  const card = add(root, 'div', 'pdx-card');
  card.style.borderLeftColor = failed
    ? palette['--pdx-bad']
    : done
      ? palette['--pdx-ok']
      : palette['--pdx-run'];

  const head = add(card, 'div', 'pdx-head');
  link(head, 'pdx-app', app, delivery.project_url);
  link(head, 'pdx-version', delivery.version || delivery.sha, delivery.commit_url);
  link(head, 'pdx-meta', delivery.ref, delivery.ref_url);
  link(head, 'pdx-meta', delivery.author, delivery.author_url);
  add(head, 'span', 'pdx-spacer');

  const clock = add(head, 'span', 'pdx-total');
  const elapsedTotal = total[delivery.sha + '|' + delivery.stage];
  clock.textContent = format(elapsedTotal);
  if (!done && !failed && elapsedTotal !== undefined) {
    clocks.push({ node: clock, base: elapsedTotal });
  }

  const links = add(head, 'nav', 'pdx-links');
  [
    ['Pipeline', delivery.pipeline_url],
    ['Merge request', delivery.mr_url],
    ['Argo CD', delivery.argocd_url],
    ['Live', liveUrl[app]],
  ].forEach((pair) => {
    if (pair[1]) {
      link(links, '', pair[0], pair[1]);
    }
  });

  const flow = add(card, 'div', 'pdx-flow');
  PHASES.forEach((phase, index) => {
    if (index) {
      add(flow, 'div', 'pdx-join');
    }
    const box = add(flow, 'div', 'pdx-phase');
    add(box, 'div', 'pdx-phase-name', phase.name);
    const chips = add(box, 'div', 'pdx-chips');

    phase.chips.forEach((chip) => {
      const indexes = chip.stages.map((stage) => STAGES.indexOf(stage));
      const first = Math.min.apply(null, indexes);
      const last = Math.max.apply(null, indexes);

      let state = 'pending';
      if (done || at > last) {
        state = 'done';
      } else if (at >= first && at <= last) {
        state = failed ? 'failed' : 'running';
      }

      const node = link(chips, 'pdx-chip pdx-' + state, undefined, delivery[chip.link]);
      add(node, 'span', 'pdx-mark', MARKS[state]);
      add(node, 'span', 'pdx-chip-label', chip.label);

      let seconds = 0;
      let counting = false;
      chip.stages.forEach((stage) => {
        if (spent[delivery.sha + '|' + stage] !== undefined) {
          seconds += spent[delivery.sha + '|' + stage];
        } else if (stage === delivery.stage && live !== undefined) {
          seconds += live;
          counting = true;
        }
      });

      if (state !== 'pending' && seconds > 0) {
        const time = add(node, 'span', 'pdx-chip-time', format(seconds));
        if (counting && state === 'running') {
          clocks.push({ node: time, base: seconds });
        }
      }
    });
  });
});

element.replaceChildren(root);

const timer = setInterval(tick, 250);
return () => clearInterval(timer);

options.styles:
.pdx {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 2px;
  font-size: 12px;
}

.pdx-empty {
  color: var(--pdx-dim);
  padding: 16px 4px;
}

.pdx-card {
  border: 1px solid var(--pdx-border);
  border-left: 3px solid var(--pdx-accent);
  border-radius: 4px;
  background: var(--pdx-panel);
  padding: 7px 9px 8px;
}

.pdx-head {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 6px;
}

.pdx-app {
  font-size: 14px;
  font-weight: 600;
}

.pdx-version {
  font-family: var(--pdx-mono);
  color: var(--pdx-dim);
}

.pdx-meta {
  color: var(--pdx-dim);
}

.pdx-spacer {
  flex: 1;
}

.pdx-total {
  font-variant-numeric: tabular-nums;
  color: var(--pdx-text);
}

.pdx-links {
  display: flex;
  gap: 6px;
}

.pdx-links a {
  border: 1px solid var(--pdx-border);
  border-radius: 3px;
  padding: 1px 7px;
  color: var(--pdx-dim);
  white-space: nowrap;
}

.pdx-links a:hover {
  color: var(--pdx-link);
  border-color: var(--pdx-link);
}

.pdx-flow {
  display: flex;
  align-items: stretch;
  overflow-x: auto;
  padding-bottom: 2px;
}

.pdx-phase {
  border: 1px solid var(--pdx-border);
  border-radius: 4px;
  background: var(--pdx-phase);
  padding: 5px;
  min-width: 118px;
}

.pdx-phase-name {
  font-weight: 600;
  color: var(--pdx-dim);
  text-transform: lowercase;
  margin: 0 2px 6px;
}

.pdx-chips {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.pdx-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  border: 1px solid var(--pdx-border);
  border-radius: 14px;
  background: var(--pdx-chip);
  padding: 2px 9px 2px 5px;
  color: var(--pdx-text);
}

.pdx-chip:hover {
  border-color: var(--pdx-link);
}

.pdx-chip-label {
  flex: 1;
  white-space: nowrap;
}

.pdx-chip-time {
  font-variant-numeric: tabular-nums;
  color: var(--pdx-dim);
  font-size: 11px;
}

.pdx-pending {
  opacity: 0.45;
}

.pdx-mark {
  width: 14px;
  height: 14px;
  flex: 0 0 14px;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9px;
  line-height: 1;
}

.pdx-done .pdx-mark {
  color: var(--pdx-ok);
}

.pdx-failed .pdx-mark {
  color: var(--pdx-bad);
}

.pdx-pending .pdx-mark {
  color: var(--pdx-dim);
}

.pdx-running .pdx-mark {
  color: var(--pdx-run);
  border-style: solid;
  border-top-color: transparent;
  animation: pdx-turn 0.9s linear infinite;
}

.pdx-running .pdx-chip-label {
  color: var(--pdx-run);
}

.pdx-join {
  width: 16px;
  height: 2px;
  flex: 0 0 16px;
  align-self: center;
  background: var(--pdx-accent);
}

@keyframes pdx-turn {
  to {
    transform: rotate(360deg);
  }
}
